namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();

    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed with some initial fake data.
        _notifications.AddRange(
        [
            CreateNotification("Welcome to the notification center!"),
            CreateNotification("Your profile was updated successfully."),
            CreateNotification("New comment on your post."),
        ]);
    }

    /// <summary>Returns all notifications available at this moment.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(int sinceId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > sinceId).ToList());
        }
    }

    /// <summary>
    /// Simulates random new notifications arriving.
    /// Called by a background service or on-demand for demo purposes.
    /// </summary>
    public void SimulateIncoming()
    {
        string[] templates =
        [
            "Server CPU usage is at {0}%.",
            "Deployment #{0} completed.",
            "User #{0} signed up.",
            "Backup #{0} finished.",
            "Alert: disk usage at {0}%.",
        ];

        lock (_lock)
        {
            var rng = Random.Shared;
            if (rng.Next(0, 3) == 0) // ~33% chance each tick
            {
                var template = templates[rng.Next(templates.Length)];
                _notifications.Add(
                    CreateNotification(string.Format(template, rng.Next(1, 999))));
            }
        }
    }

    private Notification CreateNotification(string message) =>
        new(_nextId++, message, DateTime.UtcNow);
}

namespace NotificationsApp.Services;

/// <summary>
/// Periodically generates fake notifications so the polling page has new data.
/// </summary>
public class NotificationBackgroundService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(3), stoppingToken);
            notifications.SimulateIncoming();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <strong>#@n.Id</strong> — @n.Message
                </div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> notifications = [];
    private CancellationTokenSource? _pollCts;

    // Persisted across prerender → interactive so we don't re-fetch.
    [PersistentState]
    public Notification[]? RestoredNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (RestoredNotifications is not null)
        {
            // Interactive render: state was restored from prerender — skip the fetch.
            notifications = RestoredNotifications.ToList();
        }
        else
        {
            // Prerender (or first load without persisted state): fetch from service.
            notifications = await NotificationService.GetNotificationsAsync();
            RestoredNotifications = notifications.ToArray();
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is never called during prerender, so this only
            // fires once the page is truly interactive in the browser.
            _pollCts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_pollCts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var latestId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
            var newer = await NotificationService.GetNotificationsSinceAsync(latestId);

            if (newer.Count > 0)
            {
                notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _pollCts?.Cancel();
        _pollCts?.Dispose();
    }
}

